package bookstore

import "sort"

// Cost returns the minimum total price, in cents, for a basket of books.
// Each book is identified by an integer from 1 to 5.
func Cost(books []int) int {
	// Price of a group of k distinct titles (k = 0..5).
	groupPrice := [6]int{0, 800, 1520, 2160, 2560, 3000}

	// Count copies of each title.
	counts := [5]int{}
	for _, book := range books {
		counts[book-1]++
	}
	sort.Slice(counts[:], func(i, j int) bool { return counts[i] > counts[j] })

	// Layer i is the i-th copy of every title that has at least i copies,
	// so it is a group of distinct titles and costs groupPrice[k].
	total := 0
	for i := 0; i < counts[0]; i++ {
		k := 0
		for _, c := range counts {
			if c >= i+1 {
				k++
			}
		}
		total += groupPrice[k]
	}

	// A group of five plus a group of three costs 5160, while two groups
	// of four cost 5120, so convert as many such pairs as possible.
	conversions := counts[4]
	if c3 := counts[2] - counts[3]; c3 < conversions {
		conversions = c3
	}
	total -= 40 * conversions

	return total
}
